USE `travel_share`;

SET NAMES utf8mb4;

SET FOREIGN_KEY_CHECKS=0;

START TRANSACTION;























































































-- 保证“举报成立”的演示历史与实际治理结果一致：攻略下架、评论删除。
UPDATE travel_guide g
JOIN travel_report r ON r.target_type='GUIDE' AND r.target_id=g.id AND r.status='VALID'
SET g.status='OFFLINE',g.featured=0,g.pinned=0,g.audit_opinion=CONCAT('历史举报核查成立：',r.handle_note),g.update_time=r.handle_time;
UPDATE travel_comment c
JOIN travel_report r ON r.target_type='COMMENT' AND r.target_id=c.id AND r.status='VALID'
SET c.status='DELETED',c.deleted=1,c.update_time=r.handle_time;
UPDATE travel_guide g
SET g.comment_count=(SELECT COUNT(*) FROM travel_comment c WHERE c.guide_id=g.id AND c.status='NORMAL' AND c.deleted=0);





UPDATE travel_guide g SET like_count=(SELECT COUNT(*) FROM travel_guide_like l WHERE l.guide_id=g.id),favorite_count=(SELECT COUNT(*) FROM travel_favorite f WHERE f.target_type='GUIDE' AND f.target_id=g.id),comment_count=(SELECT COUNT(*) FROM travel_comment c WHERE c.guide_id=g.id AND c.deleted=0),view_count=800+g.id*97 WHERE g.deleted=0;

UPDATE sys_user u SET follower_count=(SELECT COUNT(*) FROM travel_user_follow f WHERE f.target_user_id=u.id),following_count=(SELECT COUNT(*) FROM travel_user_follow f WHERE f.user_id=u.id),guide_count=(SELECT COUNT(*) FROM travel_guide g WHERE g.author_id=u.id AND g.deleted=0),route_count=(SELECT COUNT(*) FROM travel_route r WHERE r.user_id=u.id AND r.deleted=0),received_likes=(SELECT COALESCE(SUM(g.like_count),0) FROM travel_guide g WHERE g.author_id=u.id);

UPDATE travel_destination d SET guide_count=(SELECT COUNT(*) FROM travel_guide g WHERE g.destination_id=d.id AND g.status='PUBLISHED'),favorite_count=(SELECT COALESCE(SUM(g.favorite_count),0) FROM travel_guide g WHERE g.destination_id=d.id),view_count=(SELECT COALESCE(SUM(g.view_count),0) FROM travel_guide g WHERE g.destination_id=d.id);

UPDATE travel_tag t SET use_count=(SELECT COUNT(*) FROM travel_guide_tag gt WHERE gt.tag_id=t.id);

COMMIT;

SET FOREIGN_KEY_CHECKS=1;
