INSERT INTO travel_guide(id,guide_no,title,subtitle,cover_image,summary,author_id,destination_id,topic_id,days,budget,months,travel_mode,audience,content,expenses,tips,status,audit_status,audit_opinion,featured,pinned,view_count,like_count,favorite_count,comment_count,published_at,deleted,create_time,update_time) VALUES
(1,'GUIDE-00001','第一次去北京，三天两夜这样安排更轻松','把时间留给真正喜欢的风景','/uploads/demo/guides/guide-001.png','这是一份3天的北京旅行记录，包含路线、预算、交通和容易忽略的细节。',12,1,1,3,840,'全年','飞机+公交','亲子家庭','<h2>为什么选择北京</h2><p>北京最适合用不赶时间的方式打开。出发前我把交通、住宿区域和每天的重点写进同一张清单，实际走下来节奏很舒服。</p><figure><img src="/uploads/demo/guides/content/content-001.png" alt="北京旅行途中风景"><figcaption>清晨出发</figcaption></figure><h2>行程安排</h2><p>第一天先熟悉住处周边，第二天安排主要街区或自然景点，之后根据天气和体力灵活调整。每天只保留两到三个重点，意外发现往往比打卡更值得记住。</p><figure><img src="/uploads/demo/guides/content/content-002.png" alt="北京旅行途中风景"><figcaption>沿途的风景</figcaption></figure><h2>预算与交通</h2><p>人均预算约 840 元，包含常规交通、住宿和餐饮参考。公共交通优先，距离较远的地点集中在同一天。具体价格会随日期变化，请以实际预订页面为准。</p><figure><img src="/uploads/demo/guides/content/content-003.png" alt="北京旅行途中风景"><figcaption>一天结束前的光线</figcaption></figure><h2>旅行提醒</h2><p>提前查看天气，穿舒适鞋履，尊重当地生活与拍摄边界。涉及开放时间和费用的信息，请以当地最新公告为准。</p>','交通约 235 元；住宿约 286 元；餐饮与体验约 319 元。','行程请根据天气与体力调整；不进入未开放区域；重要信息提前离线保存。','PUBLISHED','APPROVED',NULL,1,1,0,0,0,0,DATE_SUB(NOW(),INTERVAL 1 DAY),0,DATE_SUB(NOW(),INTERVAL 269 DAY),DATE_SUB(NOW(),INTERVAL 1 DAY)),
(2,'GUIDE-00002','周末去上海，适合慢慢走的一条路线','把时间留给真正喜欢的风景','/uploads/demo/guides/guide-002.png','这是一份4天的上海旅行记录，包含路线、预算、交通和容易忽略的细节。',13,2,2,4,1200,'6-8月','高铁+步行','学生党','<h2>为什么选择上海</h2><p>上海最适合用不赶时间的方式打开。出发前我把交通、住宿区域和每天的重点写进同一张清单，实际走下来节奏很舒服。</p><figure><img src="/uploads/demo/guides/content/content-002.png" alt="上海旅行途中风景"><figcaption>值得停留的街角</figcaption></figure><h2>行程安排</h2><p>第一天先熟悉住处周边，第二天安排主要街区或自然景点，之后根据天气和体力灵活调整。每天只保留两到三个重点，意外发现往往比打卡更值得记住。</p><figure><img src="/uploads/demo/guides/content/content-003.png" alt="上海旅行途中风景"><figcaption>清晨出发</figcaption></figure><h2>预算与交通</h2><p>人均预算约 1200 元，包含常规交通、住宿和餐饮参考。公共交通优先，距离较远的地点集中在同一天。具体价格会随日期变化，请以实际预订页面为准。</p><figure><img src="/uploads/demo/guides/content/content-004.png" alt="上海旅行途中风景"><figcaption>沿途的风景</figcaption></figure><h2>旅行提醒</h2><p>提前查看天气，穿舒适鞋履，尊重当地生活与拍摄边界。涉及开放时间和费用的信息，请以当地最新公告为准。</p><figure><img src="/uploads/demo/guides/content/content-005.png" alt="上海旅行途中风景"><figcaption>一天结束前的光线</figcaption></figure>','交通约 336 元；住宿约 408 元；餐饮与体验约 456 元。','行程请根据天气与体力调整；不进入未开放区域；重要信息提前离线保存。','PUBLISHED','APPROVED',NULL,1,1,0,0,0,0,DATE_SUB(NOW(),INTERVAL 2 DAY),0,DATE_SUB(NOW(),INTERVAL 268 DAY),DATE_SUB(NOW(),INTERVAL 2 DAY)),
